package dev.patienty.assistant;import dev.patienty.patient.PatientDtos.Observation;import java.util.*;import org.springframework.stereotype.Component;@Component public class EvidenceValidator{public void validate(AssistantContext context,List<Observation> observations){Set<String>supplied=new HashSet<>();context.items().forEach(i->supplied.add(i.evidenceId()));for(Observation o:observations)if(o.evidenceIds()==null||o.evidenceIds().isEmpty()||!supplied.containsAll(o.evidenceIds()))throw new IllegalStateException("AI observation referenced invalid evidence");}}
